  "kind": "experiment",
  "portfolio": {
    "hypotheses": [
      {
        "hypothesis_id": "H1",
        "statement": "Period depends only on length, proportional to sqrt(length).",
        "confidence": 0.2
      },
      {
        "hypothesis_id": "H2",
        "statement": "Period depends on length and mass, proportional to sqrt(length/mass).",
        "confidence": 0.3
      },
      {
        "hypothesis_id": "H3",
        "statement": "Period depends on length and release angle, increasing with angle.",
        "confidence": 0.5
      }
    ]
  },
  "experiment": {
    "intent": "Vary length while holding mass and angle constant to test the sqrt(length) scaling and distinguish from mass/angle dependence.",
    "apparatus": "simple_pendulum",
    "controls": {
      "length_m": 0.2,
      "bob_mass_kg": 0.5,
      "release_angle_deg": 5.0
    },
    "readouts": ["period_s"],
    "replicates": 3,
    "forecasts": {
      "H1": {"period_s": 1.13},
      "H2": {"period_s": 0.63},
      "H3": {"period_s": 1.18}
    }
  },
  "final": null
}

